<template>
  <div class="report-chart-main">
    <div class="top-wrap-reportchart">
      <div class="top-nav-title">{{ $lang('marketing.dateSelect', '日期选择') }}</div>
      <div class="top-nav-content">
        <el-date-picker
          value-format="yyyy-MM-dd"
          size="mini"
          v-model="taskQuery.Starttime"
          type="date"
          :placeholder="$lang('marketing.startDate', '开始日期')"
        ></el-date-picker>
        <i class="el-icon-minus" style="margin:0 10px"></i>
        <el-date-picker
          value-format="yyyy-MM-dd"
          size="mini"
          v-model="taskQuery.Endtime"
          type="date"
          :placeholder="$lang('marketing.endDate', '结束日期')"
        ></el-date-picker>
        <el-cascader
          :placeholder="$lang('marketing.taskSelect', '任务选择')"
          style="margin:0 10px"
          size="mini"
          v-model="taskQuery.TaskId"
          :options="taskQueryInfo"
          :show-all-levels="false"
          :props="{ expandTrigger: 'hover', emitPath:false, label:'Label', value:'Value', children:'TaskChildren'  }"
        ></el-cascader>
        <el-button
          size="mini"
          type="primary"
          @click="doSearch"
        >{{ $lang('common.searchBtn', '搜索') }}</el-button>
        <!-- <el-cascader :show-all-levels="false" :value="value" :options="options"></el-cascader> -->
      </div>
    </div>
    <div class="middel-wrap" ref="echart"></div>
    <div class="bottom-wrap">
      <div class="table-box">
        <el-table :data="tableData" height="100%">
          <el-table-column
            fixed
            prop="date"
            width="130"
            align="center"
            :label="$lang('marketing.date', '日期')"
          ></el-table-column>
          <el-table-column
            prop="EmailSendCount"
            width="120"
            align="center"
            :label="$lang('marketing.emailSendNum', 'Email发送数量')"
          ></el-table-column>
          <el-table-column
            prop="LinkedInAddFriendCount"
            width="180"
            align="center"
            :label="$lang('marketing.linkedinFreindAddNum', 'LinkedIn好友添加数量')"
          ></el-table-column>
          <el-table-column
            prop="LinkedSendMsgCount"
            width="180"
            align="center"
            :label="$lang('marketing.linkedinMsgSendNum', 'LinkedIn消息发送数量')"
          ></el-table-column>
          <el-table-column
            prop="TwitterAddFriendCount"
            width="180"
            align="center"
            :label="$lang('marketing.twitterFriendAddNum', 'Twitter好友添加数量')"
          ></el-table-column>
          <el-table-column
            prop="TwitterSendMsgCount"
            width="180"
            align="center"
            :label="$lang('marketing.twitterMsgSendNum', 'Twitter消息发送数量')"
          ></el-table-column>
          <el-table-column
            prop="FacebookAddFriendCount"
            width="180"
            align="center"
            :label="$lang('marketing.facebookFriendAddNum', 'Facebook好友添加数量')"
          ></el-table-column>
          <el-table-column
            prop="FacebookSendMsgCount"
            width="180"
            align="center"
            :label="$lang('marketing.facebookMsgSendNum', 'Facebook消息发送数量')"
          ></el-table-column>
          <el-table-column
            prop="InstagramFollowCount"
            width="130"
            align="center"
            :label="$lang('marketing.insFollowNum', 'Instagram关注数')"
          ></el-table-column>
          <el-table-column
            prop="InstagramCancelFollowCount"
            width="130"
            align="center"
            :label="$lang('marketing.insUnfollowNum', 'Instagram取关数')"
          ></el-table-column>
          <el-table-column
            prop="InstagramSendMsgCount"
            width="180"
            align="center"
            :label="$lang('marketing.insMsgSendNum', 'Instagram消息发送数量')"
          ></el-table-column>
        </el-table>
      </div>
    </div>
  </div>
</template>
<script>
export default {
  name: 'marketingReportChart',
  data () {
    return {
      taskQuery: {
        TaskId: '',
        Starttime: '',
        Endtime: ''
      },
      taskQueryInfo: [],
      tableData: [],
      echart: ''
    }
  },
  methods: {
    /**
     * @author: vince.Liang
     * @function: 初始化页面
     * @data: 2019-3-27
     * @param {none}
     * @return: undefined
     */
    init () {
      this.loadTaskList()
      window.addEventListener('resize', this.resizeEcharts)
    },

    /**
     * @author: vince.Liang
     * @function: 加载任务列表以及默认值
     * @data: 2019-3-27
     * @param {Boolean} type 是否需要改变默认选项值并且加载报表数据
     * @return: undefined
     */
    loadTaskList (type = true) {
      this.SharpObj.getTaskQueryInfo(res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.taskQueryInfo = res.Data.TaskQueryInfo
        type && (this.taskQuery = res.Data.DefaultData)
        type && this.loadReportData()
      })
    },

    /**
     * @author: vince.Liang
     * @function: 搜索操作
     * @param {none}
     * @return: undefined
     */
    doSearch () {
      if (!this.taskQuery.Starttime || !this.taskQuery.Endtime) {
        this.$WmlMsg(this.$lang('marketing.dateNonNullTip', '开始时间与结束时间不应为空'), 'warning')
        return
      }
      this.loadReportData()
    },

    /**
     * @author: vince.Liang
     * @function: 加载报表数据
     * @data: 2019-3-27
     * @param {none}
     * @return: undefined
     */
    loadReportData () {
      this.SharpObj.getReportForm(JSON.stringify(this.taskQuery), res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        let echartSource = []
        let table = []
        for (let key in res.Data) {
          let option = []
          option.push(key)
          option.push(res.Data[key].EmailSendCount)
          option.push(res.Data[key].LinkedInAddFriendCount)
          option.push(res.Data[key].LinkedSendMsgCount)
          option.push(res.Data[key].TwitterAddFriendCount)
          option.push(res.Data[key].TwitterSendMsgCount)
          option.push(res.Data[key].FacebookAddFriendCount)
          option.push(res.Data[key].FacebookSendMsgCount)
          option.push(res.Data[key].InstagramFollowCount)
          option.push(res.Data[key].InstagramCancelFollowCount)
          option.push(res.Data[key].InstagramSendMsgCount)
          echartSource.push(option)
          res.Data[key].date = key
          table.push(res.Data[key])
        }
        this.initEchart(echartSource)
        this.tableData = table
      })
    },

    /**
     * @author: vince.Liang
     * @function: 根据数据渲染echart图表
     * @param {Array} source 返回的结果数据数组
     * @return: undedfined
     */
    initEchart (source) {
      var option = {
        legend: {},
        tooltip: {},
        dataset: {
          source: [
            [
              this.$lang('marketing.date', '日期'),
              this.$lang('marketing.emailSendNum', 'Email发送数量'),
              this.$lang('marketing.linkedinFreindAddNum', 'LinkedIn好友添加数量'),
              this.$lang('marketing.linkedinMsgSendNum', 'LinkedIn消息发送数量'),
              this.$lang('marketing.twitterFriendAddNum', 'Twitter好友添加数量'),
              this.$lang('marketing.twitterMsgSendNum', 'Twitter消息发送数量'),
              this.$lang('marketing.facebookFriendAddNum', 'Facebook好友添加数量'),
              this.$lang('marketing.facebookMsgSendNum', 'Facebook消息发送数量'),
              this.$lang('marketing.insFollowNum', 'Instagram关注数'),
              this.$lang('marketing.insUnfollowNum', 'Instagram取关数'),
              this.$lang('marketing.insMsgSendNum', 'Instagram消息发送数量')
            ],
            ...source
          ]
        },
        xAxis: { type: 'category' },
        yAxis: {
          splitLine: {
            lineStyle: {
              type: 'dashed' // 设置网格线类型 dotted：虚线   solid:实线
            },
            show: true // 隐藏或显示
          }
        },
        series: [
          { type: 'bar', color: '#909399' },
          { type: 'bar', color: '#FF7165' },
          { type: 'bar', color: '#5EA3F6' },
          { type: 'bar', color: '#FFB735' },
          { type: 'bar', color: '#37CBE3' },
          { type: 'bar', color: '#9B80F2' },
          { type: 'bar', color: '#763626' },
          { type: 'bar', color: '#FD8EC4' },
          { type: 'bar', color: '#BFBF17' },
          { type: 'bar', color: '#FFDD72' }
        ],
        dataZoom: {
          show: true,
          realtime: true,
          y: 48,
          height: 20,
          start: 0,
          end: 12
        },
        grid: {
          top: '80px',
          left: '70px',
          right: '70px',
          bottom: '30px'
        }
      }
      this.echart = this.$echarts.init(this.$refs.echart)
      this.echart.setOption(option)
    },

    /**
     * @author: vince.Liang
     * @function: 页面变动时重置echart图标尺寸
     * @data: 2019-3-27
     * @param {none}
     * @return: undefined
     */
    resizeEcharts () {
      this.echart.resize()
    }
  },
  created () {
    this.$bus.$on('delTask', (taskItem) => {
      taskItem.Id === this.taskQuery.TaskId ? this.loadTaskList() : this.loadTaskList(false)
    })
    this.$bus.$on('delGroup', (groupItem) => {
      let type = false
      for (let item of groupItem.Task) {
        if (item.Id === this.taskQuery.TaskId) {
          type = true
          break
        }
      }
      this.loadTaskList(type)
    })
  },
  beforeDestroy () {
    this.$bus.$off('delTask')
    this.$bus.$off('delGroup')
    window.removeEventListener('resize', this.resizeEcharts)
  },
  mounted () {
    this.init()
  },
  watch: {
    /**
     * @author: vince.Liang
     * @function: 监听开始时间变化，判断选择的开始时间是否符合规则
     * @param {String} newValue 新选择的开始时间
     * @param {String} value 原来的开始时间
     * @return: undefined
     */
    'taskQuery.Starttime' (newValue, value) {
      let startDate = new Date(`${newValue} 00:00:00`).getTime()
      if (new Date(new Date().toLocaleDateString()).getTime() < startDate) {
        this.$WmlMsg(this.$lang('marketing.selectDateNowTip', '选择的日期不应大于当前日期'), 'warning')
        this.taskQuery.Starttime = value
        return
      }
      if (this.taskQuery.Endtime !== '') {
        let endDate = new Date(`${this.taskQuery.Endtime} 00:00:00`).getTime()
        if (endDate < startDate) {
          this.$WmlMsg(this.$lang('marketing.startDateEndTip', '开始日期不应大于结束日期'), 'warning')
          this.taskQuery.Starttime = value
          return
        }
        if (((endDate - startDate) / (1000 * 60 * 60 * 24)) > 30) {
          this.$WmlMsg(this.$lang('marketing.selectDateRangeTip', '选择的日期范围不应大于30天'), 'warning')
          this.taskQuery.Starttime = value
        }
      }
    },

    /**
     * @author: vince.Liang
     * @function: 监听结束时间的变化，判断结束时间是否符合规则
     * @param {String} newValue 新选择的开始时间
     * @param {String} value 原来的开始时间
     * @return: undefined
     */
    'taskQuery.Endtime' (newValue, value) {
      let endDate = new Date(`${newValue} 00:00:00`).getTime()
      if (new Date(new Date().toLocaleDateString()).getTime() < endDate) {
        this.$WmlMsg(this.$lang('marketing.selectDateNowTip', '选择的日期不应大于当前日期'), 'warning')
        this.taskQuery.Endtime = value
        return
      }
      if (this.taskQuery.Starttime !== '') {
        let startDate = new Date(`${this.taskQuery.Starttime} 00:00:00`).getTime()
        if (endDate < startDate) {
          this.$WmlMsg(this.$lang('marketing.startDateEndTip', '结束日期不应小于开始日期'), 'warning')
          this.taskQuery.Endtime = value
          return
        }
        if (((endDate - startDate) / (1000 * 60 * 60 * 24)) > 30) {
          this.$WmlMsg(this.$lang('marketing.selectDateRangeTip', '选择的日期范围不应大于30天'), 'warning')
          this.taskQuery.Endtime = value
        }
      }
    }
  }
}
</script>
<style lang="scss" scoped>
.report-chart-main {
  width: 100%;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background-color: #fff;
  .top-wrap-reportchart {
    flex-shrink: 0;
    width: 100%;
    display: flex;
    align-items: center;
    padding: 20px;
    .top-nav-title {
      flex-shrink: 0;
      padding-right: 30px;
      font-size: 15px;
      font-weight: 600;
    }
    .top-nav-content {
      flex-grow: 1;
    }
  }
  .middel-wrap {
    width: 100%;
    height: 300px;
    flex-shrink: 0;
  }
  .bottom-wrap {
    flex-grow: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    .table-box {
      flex-grow: 1;
      min-height: 0;
      padding: 10px;
      box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
    }
  }
}
</style>
